<?php
declare(strict_types=1);
require __DIR__.'/core.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
try {
 $method=$_SERVER['REQUEST_METHOD']; if(!in_array($method,['GET','POST']))fail('Metoden støttes ikke.',405);
 $in=[];if($method==='POST'){if(strtolower(trim(explode(';',$_SERVER['CONTENT_TYPE']??'')[0]))!=='application/json')fail('Bruk JSON.',415);if((int)($_SERVER['CONTENT_LENGTH']??0)>12000)fail('For mye innhold.',413);$in=json_decode(file_get_contents('php://input'),true);if(!is_array($in))fail('Ugyldig forespørsel.');$origin=$_SERVER['HTTP_ORIGIN']??'';$expected=(isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.($_SERVER['HTTP_HOST']??'');if($origin!==''&&!hash_equals($expected,$origin))fail('Ugyldig opphav.',403);}
 $result=transact(function(&$db) use($method,$in){
  if($method==='POST'&&($in['action']??'')==='activate') { $t=$in['token']??'';if(!is_string($t)||!preg_match('/^[a-f0-9]{64}$/D',$t))fail('Invitasjonen er ugyldig eller brukt.',401);$hash=hash('sha256',$t);$invite=$db['invites'][$hash]??null;if(!$invite||$invite['expires']<time())fail('Invitasjonen er ugyldig eller brukt.',401);unset($db['invites'][$hash]);$key=token();$db['keys'][hash('sha256',$key)]=['hotel'=>$invite['hotel'],'player'=>$invite['player'],'csrf'=>token()];setcookie('hotel_device',$key,['expires'=>time()+31536000,'path'=>'/hotell/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);return ['ok'=>true]; }
  $who=auth($db);if(!$who)fail('Åpne den personlige invitasjonen din for å komme inn.',401);$s=&$db['hotels'][$who['hotel']];if(!$s)fail('Hotellet finnes ikke.',401);$now=time(); foreach($s['players'] as &$p)if($p['id']===$who['player']){$p['seen']=$now;$me=['id'=>$p['id'],'name'=>$p['name']];}unset($p);tick($s,$now);
  if($method==='POST') {if(!hash_equals($who['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))fail('Last siden på nytt og prøv igjen.',403);$id=$in['id']??'';if(!is_string($id)||!preg_match('/^[a-zA-Z0-9_-]{12,80}$/D',$id))fail('Handlingen mangler gyldig ID.');$dedupe=$who['player'].':'.$id;if(!isset($s['handled'][$dedupe])){if(!isset($in['rev'])||(int)$in['rev']!==$s['rev']){return ['ok'=>false,'error'=>'Hotellet ble oppdatert. Prøv igjen.','status'=>409,'state'=>publicState($s,$now),'csrf'=>$who['csrf'],'me'=>$me,'serverTime'=>$now];} action($s,$who['player'],$in,$now);$s['handled'][$dedupe]=$now;if(count($s['handled'])>2000)$s['handled']=array_slice($s['handled'],-1500,null,true);}}
  return ['ok'=>true,'state'=>publicState($s,$now),'csrf'=>$who['csrf'],'me'=>$me,'serverTime'=>$now]; });
 if(isset($result['status']))http_response_code($result['status']);echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
